code:
try:
    x = int("42")
except ValueError:
    print("bad")
else:
    print("good", x)
finally:
    print("done")

def f():
    try:
        return "try"
    finally:
        print("finally")
print(f())

try:
    {}["k"]
except LookupError:
    print("lookup")
except KeyError:
    print("key")

def f():
    try:
        raise ValueError("x")
    except ValueError:
        raise
try:
    f()
except ValueError as e:
    print("caught", e)

class M:
    def __enter__(self):
        return 42
    def __exit__(self, *a):
        return False
with M() as x:
    print(x)

class M:
    def __enter__(self):
        return self
    def __exit__(self, t, v, tb):
        return True
with M():
    1 / 0
print("after")

from contextlib import contextmanager
@contextmanager
def cm():
    print("in")
    yield
    print("out")
try:
    with cm():
        raise ValueError
except ValueError:
    print("caught")

from contextlib import contextmanager
@contextmanager
def cm():
    try:
        yield 1
    finally:
        print("cleanup")
with cm() as v:
    print(v)
print("end")
